import{_ as e,c as r,o as t,H as i}from"./chunks/framework.B03ETCDl.js";const n="/images/posts/ci/01.png",C=JSON.parse('{"title":"연계정보(CI)도 암호화 해야하나요?","description":"","frontmatter":{"title":"연계정보(CI)도 암호화 해야하나요?","date":"2025-11-08T19:00+09:00"},"headers":[],"relativePath":"posts/ci.md","filePath":"posts/ci.md","lastUpdated":1779921811000}'),o={name:"posts/ci.md"};function s(l,a,p,c,m,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="연계정보-ci-도-암호화-해야하나요" tabindex="-1">연계정보(CI)도 암호화 해야하나요? <a class="header-anchor" href="#연계정보-ci-도-암호화-해야하나요" aria-label="Permalink to &quot;연계정보(CI)도 암호화 해야하나요?&quot;">​</a></h1><p>회원가입과 아이디 그리고 비밀번호 찾는 과정에서 본인인증(Identity Verification) 과정을 도입했어요. 사용자가 서비스를 이용할 때 반드시 전화번호가 필요했고 이를 수집하기 위해서 본인인증을 이용하기로 했습니다. 포트원의 <a href="https://developers.portone.io/opi/ko/integration/pg/v2/inicis-unified-identity-verification?v=v2" target="_blank" rel="noreferrer">KG이니시스 통합인증</a>을 사용하면 간편인증을 통해서 본인인증 요청한 사람의 <mark>전화번호와 연계정보(CI, Connecting Information)</mark> 을 가져올 수 있어요.</p><h3 id="본인인증을-완료하면-연계정보-ci-를-받아요" tabindex="-1">본인인증을 완료하면 연계정보(CI)를 받아요. <a class="header-anchor" href="#본인인증을-완료하면-연계정보-ci-를-받아요" aria-label="Permalink to &quot;본인인증을 완료하면 연계정보(CI)를 받아요.&quot;">​</a></h3><details><summary>포트원 인증정보 살펴보기</summary><p><img src="'+n+'" alt=""></p></details><p>서비스 사용자가 <mark>KG이니시스 통합인증 창</mark>을 통해서 선택한 방법으로 본인인증을 완료하고나면 백엔드 서버에서는 본인인증 요청 아이디를 사용해서 인증정보를 가져올 수 있어요. 일반적으로 인증 정보에는 연계정보(CI), 중복가입확인정보(DI) 그리고 전화번호를 포함하지만 KG이니시스에서는 <a href="https://manual.inicis.com/sa/auth.html" target="_blank" rel="noreferrer">본인확인에 해당되는 경우에만 DI 정보를 제공</a>하기 때문에 <mark>간편인증에 해당되는 KG이니시스 통합인증은 중복가입확인정보(DI)을 제공받을 수 없죠.</mark> 중복가입이라는 요구사항은 필요없다고 하였기에 연계정보만 활용할 수 있으면 될 것 같습니다.</p><blockquote><p>다만, KG이니시스 통합인증의 카카오톡 인증 시 CI 값을 받기 위해서는 별도 계약을 해야한다는 건 중요해요.</p></blockquote><h3 id="연계정보-ci-도-암호화-해야하나요-1" tabindex="-1">연계정보(CI)도 암호화 해야하나요? <a class="header-anchor" href="#연계정보-ci-도-암호화-해야하나요-1" aria-label="Permalink to &quot;연계정보(CI)도 암호화 해야하나요?&quot;">​</a></h3><details><summary>CI란 무엇인가요?</summary><p><img src="https://mblogthumb-phinf.pstatic.net/MjAyNDAyMjNfMjQy/MDAxNzA4NjUzNDMxNDk1.DpNy3O5hl6mht3_h23JtYpqjMgAKUnXLPQan8JprT9cg.FK1HOrMUCWaqH-T49dnDnjEXaXNqlrelk_SqI15WO9Ig.PNG/03.png?type=w800" alt=""></p></details><p>연계정보(CI)는 주민등록번호 수집이 원칙적으로 금지되면서 주민등록번호 대신하기 위해서 <a href="https://identity.kisa.or.kr/web/main/contents/M010-03" target="_blank" rel="noreferrer">본인확인기관에서 발급</a>한 개인을 식별할 수 있는 값이면서 주민등록번호를 기반으로 만들어지기 때문에 개인정보보호법 상 개인정보로 분류됩니다. 그런데, 연계정보(CI)는 주민등록번호를 단방향 암호화(해시 알고리즘)을 적용해서 만들어놓은 값이라서 이미 암호화된 값을 다시 암호화해서 저장해야하는가를 고민할 수 있어요.</p><p><a href="https://www.law.go.kr/LSW//admRulInfoP.do?admRulSeq=2100000259318&amp;chrClsCd=010201" target="_blank" rel="noreferrer">연계정보의 생성·처리 등에 관한 기준</a>의 <mark>제11조 연계정보 이용기관의 안전조치</mark> 항을 참고하면 일정 규모 이상의 연계정보를 보유하는 경우에는 반드시 연계정보를 암호화해서 안전하게 저장하고 개인을 식별할 수 있는 다른 정보와 분리해서 저장하는 등의 관리 조치가 필요해요. <a href="https://namu.wiki/w/%EB%A1%AF%EB%8D%B0%EC%B9%B4%EB%93%9C%20%EA%B0%9C%EC%9D%B8%EC%8B%A0%EC%9A%A9%EC%A0%95%EB%B3%B4%20%EC%9C%A0%EC%B6%9C%20%EC%82%AC%EA%B3%A0" target="_blank" rel="noreferrer">롯데카드 개인신용정보 유출 사고</a>처럼 수 많은 이용자의 연계정보를 이용하는 기관에서는 <a href="https://www.korea.kr/briefing/pressReleaseView.do?newsId=156725761" target="_blank" rel="noreferrer">연계정보 유출 방지를 위한 안전조치가 필요하다</a>는 걸 알 수 있어요.</p><p><a href="https://blog.naver.com/n_privacy/223397387470" target="_blank" rel="noreferrer">연계정보(CI)</a>를 활용하는 대표적인 서비스는 금융 마이데이터라고 할 수 있어요. 사용자에게 직접 주민등록번호를 제공받지 않고 본인인증을 통해 CI 값을 받아서 개인을 식별하는거죠. 우리는 회원가입 시 본인인증으로 가져온 연계정보(CI)를 전화번호와 함께 저장하고 아이디 찾기 과정에서 연계정보(CI) 값을 매칭하여 아이디를 가져올 수 있도록 추가했어요. 그리고 우선은 <mark>연계정보(CI)를 암호화하지 않고 저장하고 있어요</mark>.</p><p>연계정보(CI)로 주민등록번호를 알아낼 수는 없지만 주민등록번호가 변하지 않는 한 변경될 수 없는 유일한 값이기 때문에 여러분은 반드시 개인정보라는 인식을 가지고 서비스 규모와 상관없이 암호화해서 안전하게 저장하고 활용하는게 좋을 것 같아요!</p>',12)])])}const f=e(o,[["render",s]]);export{C as __pageData,f as default};
